import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

if (!supabaseUrl || !supabaseKey) {
  console.error('Missing Supabase credentials:', { supabaseUrl: !!supabaseUrl, supabaseKey: !!supabaseKey })
}

const supabase = createClient(supabaseUrl!, supabaseKey!)

export async function POST(request: NextRequest) {
  try {
    const data = await request.json()
    console.log('Received data:', data)

    // Validar que los campos requeridos existan
    const { nombre, email, telefono, canal_preferido, tipo_proyecto, ubicacion_proyecto, area, presupuesto, plazo, etapa, mensaje } = data

    if (!nombre || !email || !telefono || !canal_preferido || !tipo_proyecto || !ubicacion_proyecto || !presupuesto || !plazo || !etapa) {
      return NextResponse.json(
        { error: 'Faltan campos requeridos' },
        { status: 400 }
      )
    }

    // Insertar en Supabase
    const { data: insertedData, error } = await supabase
      .from('contactos')
      .insert([
        {
          nombre,
          email,
          telefono,
          canal_preferido,
          tipo_proyecto,
          ubicacion_proyecto,
          area: area ? parseFloat(area) : null,
          presupuesto,
          plazo,
          etapa,
          mensaje: mensaje || null,
        },
      ])
      .select()

    if (error) {
      console.error('Supabase error:', error)
      return NextResponse.json(
        { error: `Error al guardar el contacto: ${error.message}` },
        { status: 500 }
      )
    }

    console.log('Successfully inserted:', insertedData)
    return NextResponse.json(
      { success: true, data: insertedData, message: 'Contacto guardado correctamente' },
      { status: 200 }
    )
  } catch (error) {
    console.error('Error in API route:', error)
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Error en el servidor' },
      { status: 500 }
    )
  }
}
